const rows = $input.all(); 

let universities = {};
let courses = [];

rows.forEach((item, index) => {
  const row = item.json;
  const uniId = row["University ID"];

  // Store university only once
  if (!universities[uniId]) {
    universities[uniId] = {
      university_id: uniId,
      university_name: row["University Name"],
      university_type: row["University Type"],   // ✅ Added university type
      location: row["Location"],
      year_established: row["Year Established"],
      fees: row["School Fees (₦)"]
    };
  }

  // Push course row
  courses.push({
    course_id: index + 1, // auto id
    university_id: uniId,
    course_name: row["Course"],
    jamb_cutoff: row["JAMB Cut-off Mark"],
    waec_requirements: row["WAEC Requirements"]
  });
});

return [
  { json: { universities: Object.values(universities) } },
  { json: { courses } }
];

