// ======================
// INPUTS
// ======================
const waecNode = $('Waec').first().json; // fallback reference
const webhookData = $json; // this node’s input

// Prefer webhookData, fallback to Waec node
const subjects = webhookData.subjects || waecNode.subjects || [];
const jambScore = parseInt(webhookData.jambScore) || parseInt(waecNode.jambScore) || 0;
const preferredCourse = webhookData.preferredCourse || waecNode.preferredCourse || "";
const region = webhookData.region || waecNode.region || "";
const preferredUniversities = webhookData.preferredUniversities || waecNode.preferredUniversities || {};

// Universities data comes from input
const universities = $input.all();

// ======================
// WAEC GRADES
// ======================
const gradeValues = {
  'A1': 1, 'B2': 2, 'B3': 3, 'C4': 4, 'C5': 5, 'C6': 6,
  'D7': 7, 'E8': 8, 'F9': 9
};

// Subjects with credits
const creditSubjects = (subjects || [])
  .filter(s => (gradeValues[s.grade] || 10) <= 6)
  .map(s => s.subject);

const hasEnglish = creditSubjects.some(s => s.toLowerCase().includes('english'));
const hasMaths = creditSubjects.some(s => s.toLowerCase().includes('math'));
const creditCount = creditSubjects.length;

// Student profile
const studentData = {
  subjects,
  jambScore,
  preferredCourse,
  region,
  preferredUniversities: {
    federal: preferredUniversities.federal || [],
    state: preferredUniversities.state || [],
    private: preferredUniversities.private || []
  },
  waec_analysis: {
    credit_subjects: creditSubjects,
    credit_count: creditCount,
    has_english: hasEnglish,
    has_maths: hasMaths,
    meets_minimum: hasEnglish && hasMaths && creditCount >= 5
  }
};

// ======================
// HELPERS
// ======================
function normalizeUniType(typeString) {
  if (!typeString) return null;
  const t = typeString.toString().toLowerCase();
  if (t.includes('federal') || t.includes('fed')) return 'federal';
  if (t.includes('state') || t.includes('st') || t.includes('lasu') || t.includes('rsu')) return 'state';
  if (t.includes('private') || t.includes('ptv') || t.includes('poly') || t.includes('college')) return 'private';
  // fallback: try to see if it contains any known university names that indicate federal
  return null;
}

function getUniversityTypeFromName(universityName) {
  const name = (universityName || "").toLowerCase();
  if (name.includes('federal') || 
      ['university of ibadan', 'university of lagos', 'university of nigeria',
       'obafemi awolowo', 'ahmadu bello', 'university of benin',
       'university of ilorin'].some(fed => name.includes(fed))) {
    return 'federal';
  }
  if (name.includes('state') || name.includes('lasu') || name.includes('rsu')) {
    return 'state';
  }
  return 'private';
}

function checkWAECEligibility(waecRequirements, studentData) {
  const required = (waecRequirements || "").toLowerCase();
  const studentCreditSubjects = studentData.waec_analysis.credit_subjects.map(s => s.toLowerCase());

  if (!studentData.waec_analysis.has_english) return { eligible: false, missing: ['English Language'] };
  if (!studentData.waec_analysis.has_maths) return { eligible: false, missing: ['Mathematics'] };
  if (studentData.waec_analysis.credit_count < 5) return { eligible: false, missing: ['Need 5 credits total'] };

  const missing = [];

  if (required.includes('physics') && !studentCreditSubjects.some(s => s.includes('physic'))) {
    missing.push('Physics');
  }
  if (required.includes('chemistry') && !studentCreditSubjects.some(s => s.includes('chemistry') || s.includes('chem'))) {
    missing.push('Chemistry');
  }
  if (required.includes('biology') && !studentCreditSubjects.some(s => s.includes('biology') || s.includes('bio'))) {
    missing.push('Biology');
  }
  if (required.includes('literature') && !studentCreditSubjects.some(s => s.includes('literature') || s.includes('lit'))) {
    missing.push('Literature in English');
  }
  if (required.includes('government') && !studentCreditSubjects.some(s => s.includes('government') || s.includes('govt'))) {
    missing.push('Government');
  }
  if (required.includes('economics') && !studentCreditSubjects.some(s => s.includes('economics') || s.includes('econ'))) {
    missing.push('Economics');
  }

  return {
    eligible: missing.length === 0,
    missing
  };
}

function extractJAMBCutoff(cutoffString) {
  if (!cutoffString) return 140;
  const match = cutoffString.toString().match(/(\d+)/);
  return match ? parseInt(match[1]) : 140;
}

function extractFees(feesString) {
  if (!feesString) return 0;
  const cleaned = feesString.toString().replace(/,/g, '');
  const match = cleaned.match(/(\d+)/);
  return match ? parseInt(match[1]) : 0;
}

// ======================
// UNIVERSITY PROCESSING
// ======================
const results = {
  eligible: [],
  maybeEligible: [],
  notEligible: [],
  recommended: [],
  byType: {
    federal: { eligible: [], maybeEligible: [] },
    state: { eligible: [], maybeEligible: [] },
    private: { eligible: [], maybeEligible: [] }
  }
};

universities.forEach(item => {
  const uni = item.json;

  // Use the uni.university_type if available, otherwise normalize or infer from name
  let uniType = normalizeUniType(uni.university_type) || getUniversityTypeFromName(uni.university_name);
  if (!['federal','state','private'].includes(uniType)) uniType = 'private'; // safe default

  // Looser course matching: if preferredCourse empty allow all
  if (preferredCourse && (!uni.course_name || !uni.course_name.toLowerCase().includes(preferredCourse.toLowerCase().split(' ')[0]))) {
    return;
  }

  const jambCutoff = extractJAMBCutoff(uni.jamb_cutoff);
  const fees = extractFees(uni.fees);
  const waecCheck = checkWAECEligibility(uni.waec_requirements || '', studentData);

  const jambDifference = jambScore - jambCutoff;
  const isPreferred = studentData.preferredUniversities[uniType]?.includes(uni.university_name) || false;
  const matchesRegion = !region || (uni.location?.toLowerCase().includes(region.toLowerCase()));

  const uniResult = {
    ...uni,
    university_type: uniType,
    jamb_cutoff_numeric: jambCutoff,
    fees_numeric: fees,
    jamb_difference: jambDifference,
    waec_eligible: waecCheck.eligible,
    waec_missing_subjects: waecCheck.missing,
    is_preferred: isPreferred,
    matches_region: matchesRegion,
    match_score: (
      (jambDifference >= 0 ? 50 : 0) +
      (waecCheck.eligible ? 30 : 0) +
      (isPreferred ? 15 : 0) +
      (matchesRegion ? 5 : 0)
    )
  };

  if (jambDifference >= 0 && waecCheck.eligible) {
    results.eligible.push(uniResult);
    results.byType[uniType].eligible.push(uniResult);

    if (jambDifference >= 20 || isPreferred) {
      results.recommended.push(uniResult);
    }
  } else if (jambDifference >= -15 || waecCheck.eligible) {
    results.maybeEligible.push(uniResult);
    results.byType[uniType].maybeEligible.push(uniResult);
  } else {
    results.notEligible.push(uniResult);
  }
});

// ======================
// SORTING
// ======================
const sortByScore = (a, b) => b.match_score - a.match_score;
results.eligible.sort(sortByScore);
results.maybeEligible.sort(sortByScore);
results.recommended.sort(sortByScore);

Object.keys(results.byType).forEach(type => {
  results.byType[type].eligible.sort(sortByScore);
  results.byType[type].maybeEligible.sort(sortByScore);
});

// ======================
// FINAL RETURN
// ======================
return [{
  json: {
    student: studentData,
    analysis: {
      total_eligible: results.eligible.length,
      total_maybe: results.maybeEligible.length,
      total_not_eligible: results.notEligible.length,
      has_good_options: results.eligible.length > 0,
      top_recommended_count: results.recommended.length,
      by_type: {
        federal: {
          eligible_count: results.byType.federal.eligible.length,
          maybe_count: results.byType.federal.maybeEligible.length
        },
        state: {
          eligible_count: results.byType.state.eligible.length,
          maybe_count: results.byType.state.maybeEligible.length
        },
        private: {
          eligible_count: results.byType.private.eligible.length,
          maybe_count: results.byType.private.maybeEligible.length
        }
      }
    },
    universities: {
      top_recommended: results.recommended.slice(0, 5),
      eligible: results.eligible.slice(0, 15),
      maybeEligible: results.maybeEligible.slice(0, 10),
      by_type: {
        federal: {
          eligible: results.byType.federal.eligible.slice(0, 5),
          maybeEligible: results.byType.federal.maybeEligible.slice(0, 3)
        },
        state: {
          eligible: results.byType.state.eligible.slice(0, 5),
          maybeEligible: results.byType.state.maybeEligible.slice(0, 3)
        },
        private: {
          eligible: results.byType.private.eligible.slice(0, 5),
          maybeEligible: results.byType.private.maybeEligible.slice(0, 3)
        }
      }
    }
  }
}];

// Get webhook body
const body = $input.first().json.body;

// Extract fields
const subjects = body.subjects || [];
const jambScore = parseInt(body.jambScore) || 0;
const preferredCourse = body.preferredCourse || "";
const region = body.region || "";
const preferredUniversities = body.preferredUniversities || {};

// Grade mapping
const gradeValues = {
  'A1': 1, 'B2': 2, 'B3': 3, 'C4': 4, 'C5': 5, 'C6': 6,
  'D7': 7, 'E8': 8, 'F9': 9
};

// Get credit subjects (grade <= 6)
const creditSubjects = subjects
  .filter(s => (gradeValues[s.grade] || 10) <= 6)
  .map(s => s.subject);

const hasEnglish = subjects.some(s => 
  (gradeValues[s.grade] || 10) <= 6 && s.subject.toLowerCase().includes("english")
);

const hasMaths = subjects.some(s => 
  (gradeValues[s.grade] || 10) <= 6 && s.subject.toLowerCase().includes("math")
);

// Build output
return [
  {
    json: {
      subjects,
      jambScore,
      preferredCourse,
      region,
      preferredUniversities: {
        federal: preferredUniversities.federal || [],
        state: preferredUniversities.state || [],
        private: preferredUniversities.private || []
      },
      waec_analysis: {
        credit_subjects: creditSubjects,
        credit_count: creditSubjects.length,
        has_english: hasEnglish,
        has_maths: hasMaths,
        meets_minimum: hasEnglish && hasMaths && creditSubjects.length >= 5
      }
    }
  }
];

// Get the data from the previous node
const input = $json;  // This is the raw JSON from the last node

// Build and normalize output to always match frontend schema
return [
  {
    json: {
      overview: input.overview || $input.first().json.output.overview,
      top_recommended: input.top_recommended || $input.first().json.output.top_recommended,
      other_eligible: input.other_eligible || $input.first().json.output.other_eligible,
      borderline_options: input.borderline_options || $input.first().json.output.borderline_options,
      key_recommendations: input.key_recommendations || $input.first().json.output.key_recommendations,
      missing_requirements: input.missing_requirements || $input.first().json.output.missing_requirements
    }
  }
];

const rows = $input.all(); 

let universities = {};
let courses = [];

rows.forEach((item, index) => {
  const row = item.json;
  const uniId = row["University ID"];

  // Store university only once
  if (!universities[uniId]) {
    universities[uniId] = {
      university_id: uniId,
      university_name: row["University Name"],
      university_type: row["University Type"],   // ✅ Added university type
      location: row["Location"],
      year_established: row["Year Established"],
      fees: row["School Fees (₦)"]
    };
  }

  // Push course row
  courses.push({
    course_id: index + 1, // auto id
    university_id: uniId,
    course_name: row["Course"],
    jamb_cutoff: row["JAMB Cut-off Mark"],
    waec_requirements: row["WAEC Requirements"]
  });
});

return [
  { json: { universities: Object.values(universities) } },
  { json: { courses } }
];
